cssCode:
#container { width: 100%; height: 100%; position: relative; background: #0a0a0a; overflow: hidden; cursor: none; }

/* કંટાળાજનક લેયર */
.boring-layer {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  color: #333; font-size: 50px; font-weight: 900; font-family: sans-serif;
  background: #0a0a0a; z-index: 1; pointer-events: none;
}
/* જાદુઈ કલરફુલ લેયર */
.magic-layer {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 50px; font-weight: 900; font-family: sans-serif;
  background: linear-gradient(45deg, #ff007f, #6c63ff, #00ffcc);
  z-index: 2; pointer-events: none;
  /* ક્લિપ પાથ લેન્સની જેમ કામ કરશે */
  clip-path: circle(0px at var(--x, 50%) var(--y, 50%));
  transition: clip-path 0.1s ease-out;
}
.magic-layer span { text-shadow: 0 5px 20px rgba(0,0,0,0.5); }
/* કાચની ફ્રેમ (Lens Border) */
.glass-ring {
  position: absolute; width: 160px; height: 160px;
  border-radius: 50%; border: 2px solid rgba(255,255,255,0.5);
  box-shadow: 0 0 20px rgba(0,255,204,0.5), inset 0 0 10px rgba(255,0,127,0.3);
  transform: translate(-50%, -50%); top: -200px; left: -200px;
  pointer-events: none; z-index: 5; backdrop-filter: blur(2px);
  transition: width 0.2s, height 0.2s;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:#0a0a0a;overflow:hidden;';

c.innerHTML = `
  <div class="boring-layer">NOTHING HERE</div>
  <div class="magic-layer" id="mLayer"><span>PURE MAGIC</span></div>
  <div class="glass-ring" id="gRing"></div>
`;

const mLayer = document.getElementById('mLayer');
const gRing = document.getElementById('gRing');

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  // આંગળીની નીચે કલરફુલ લેયર દેખાશે
  mLayer.style.clipPath = `circle(80px at ${x}px ${y}px)`;

  // ગ્લાસ રીંગને આંગળીની પાછળ પાછળ ચલાવવી
  gRing.style.left = `${x}px`;
  gRing.style.top = `${y}px`;
});

c.addEventListener('pointerdown', () => {
  // ક્લિક કરતા લેન્સ મોટો થાય છે
  mLayer.style.clipPath = `circle(120px at ${gRing.style.left} ${gRing.style.top})`;
  gRing.style.width = '240px';
  gRing.style.height = '240px';
});

c.addEventListener('pointerup', () => {
  mLayer.style.clipPath = `circle(80px at ${gRing.style.left} ${gRing.style.top})`;
  gRing.style.width = '160px';
  gRing.style.height = '160px';
});

c.addEventListener('pointerleave', () => {
  mLayer.style.clipPath = `circle(0px at 50% 50%)`;
  gRing.style.left = `-200px`; // છુપાવી દેવું
});
